package com.travbook.journeys.adapter.out.commerce;
import com.travbook.journeys.application.port.out.JourneySelection;
import com.travbook.journeys.domain.model.Journey.*;
import com.travbook.journeys.domain.model.Journey;
import com.travbook.buses.application.port.in.DiscoverBuses;
import com.travbook.cabs.application.port.in.DiscoverCabs;
import com.travbook.holidays.application.port.in.ExploreHolidays;
import com.travbook.holidays.domain.model.Holiday;
import com.travbook.shared.domain.*;
import java.time.*;
import java.util.*;
import java.math.*;
public final class DiscoverySelectionAdapter implements JourneySelection {
 private final DiscoverBuses buses;private final DiscoverCabs cabs;private final ExploreHolidays holidays;
 public DiscoverySelectionAdapter(DiscoverBuses b,DiscoverCabs c,ExploreHolidays h){buses=b;cabs=c;holidays=h;}
 public Selection select(CustomerIdentity identity,Request r){return switch(r.kind()){
  case BUS -> bus(r);
  case CAB -> cab(r);
  case HOLIDAY -> {var original=holidays.quote(identity,r.sourceId());if(original.travelPackage().fulfilment()==Holiday.Fulfilment.ENQUIRY&&holidays.enquiryForQuote(identity,original.id())==null)Journey.conflict("Record the owned enquiry before requesting supplier booking terms.");yield holiday(r,holidays.revalidateForBooking(original.owner(),original.id()));}
 };}
 private String policy(Instant until){return "MOCK sample policy: full refund of all quoted components before "+until+". No cancellation or rescheduling through this adapter after that deadline. Full simulated payment at checkout; no real charge.";}
 private Selection bus(Request r){var d=buses.trip(r.sourceId(),r.offerId(),false);var f=buses.reprice(r.sourceId(),r.offerId(),r.seats(),r.boardingId(),r.droppingId());if(!f.complete())Journey.invalid("Select a seat for every passenger.");var t=d.trip();var details=new ArrayList<String>();details.add(t.operator()+" / "+t.type());var boarding=t.boarding().stream().filter(p->p.id().equals(r.boardingId())).findFirst().orElseThrow();var dropping=t.dropping().stream().filter(p->p.id().equals(r.droppingId())).findFirst().orElseThrow();details.add("Boarding: "+boarding.name()+" at "+boarding.time()+" / "+t.timezone());details.add("Drop-off: "+dropping.name()+" at "+dropping.time()+" / "+t.timezone());details.add("Arrival: "+t.arrivalAt());details.add(t.instructions());var cs=f.seats().stream().map(s->new Component(s.id(),"Seat "+s.id()+" / "+s.deck(),s.fare())).toList();var until=t.departureAt().minusSeconds(7200);return new Selection(r,t.supplier(),t.id().toString(),t.origin()+" to "+t.destination(),t.departureAt(),t.timezone(),d.criteria().passengerAges(),details,cs,f.total(),d.expiresAt(),until,policy(until));}
 private Selection cab(Request r){var d=cabs.detail(r.sourceId(),r.offerId());var f=cabs.reprice(r.sourceId(),r.offerId());var o=f.offer();var c=d.criteria();var details=new ArrayList<String>();details.add(c.type()+" / "+o.category()+"; passengers "+c.passengers()+", luggage "+c.luggage());details.add("Pickup: "+c.pickup()+"; drop-off: "+c.dropoff());details.add("Included: "+o.includedKm()+" km / "+o.includedHours()+" hours");details.add("Extra km INR "+o.extraKm().amount()+"; extra hour INR "+o.extraHour().amount());details.addAll(o.inclusions());details.addAll(o.exclusions());details.add(o.assumptions());if(o.returnAt()!=null)details.add("Return: "+o.returnAt());details.add("Vehicle category reservation and assignment are separate. This is not a live driver, registration or GPS feed.");var until=o.pickupAt().minusSeconds(7200);return new Selection(r,o.supplier(),o.id().toString(),c.pickup()+" to "+c.dropoff(),o.pickupAt(),o.timezone(),Collections.nCopies(c.passengers(),-2),details,List.of(new Component("transport","Vehicle category, taxes and booking fee",o.total())),o.total(),d.expiresAt(),until,policy(until));}
 private Selection holiday(Request r,Holiday.Quote q){var p=q.travelPackage();var details=new ArrayList<String>();details.add("MOCK supplier quotation for a preassembled single-provider package; not a real supplier response.");details.add("Departure: "+q.selection().departure()+" / "+p.nights()+" nights");for(var day:p.itinerary())details.add("Day "+day.day()+": "+day.title()+" — "+day.description()+"; hotel "+day.hotel()+"; meals "+day.meals()+"; transport "+day.transport());details.addAll(p.inclusions());details.addAll(p.exclusions());details.add(p.eligibility());var ages=new ArrayList<Integer>(Collections.nCopies(q.selection().adults(),-1));ages.addAll(q.selection().childAges());var departure=q.selection().departure().atTime(10,0).atZone(ZoneId.of(p.timezone())).toInstant();var total=q.total().decimal();var hotel=TravelMoney.inr(total.multiply(new BigDecimal("0.60")));var transfer=TravelMoney.inr(total.multiply(new BigDecimal("0.25")));var activity=TravelMoney.inr(total.subtract(hotel.decimal()).subtract(transfer.decimal()));var cs=List.of(new Component("accommodation","All accommodation and meals (sample allocation)",hotel),new Component("transfers","Included transfers (sample allocation)",transfer),new Component("activities","Included activities and remaining taxes/fees (sample allocation)",activity));var until=departure.minusSeconds(86400);return new Selection(r,p.supplier(),p.id()+":"+q.selection().departure(),p.title(),departure,p.timezone(),ages,details,cs,q.total(),q.expiresAt(),until,policy(until));}
 public void validate(Quote q){var r=q.selection().request();var fresh=switch(r.kind()){case BUS->bus(r);case CAB->cab(r);case HOLIDAY->holiday(r,holidays.revalidateForBooking(q.owner(),r.sourceId()));};if(!fresh.total().equals(q.selection().total())||!fresh.components().equals(q.selection().components())||!fresh.departureAt().equals(q.selection().departureAt())||!fresh.supplier().equals(q.selection().supplier())||!fresh.details().equals(q.selection().details()))Journey.conflict("Supplier price or terms changed. Accept a new quotation before paying.");}
}
